from pathlib import Path
p=Path('src/components/personal-account.tsx');s=p.read_text(encoding='utf-8')
s=s.replace('Warehouse, Plus, Pencil, Trash2, LockKeyhole','Warehouse, Plus, Pencil, Trash2')
s=s.replace("const [section", "const [section")
a=s.index(' const orgFields=');b=s.index('\n return ',a);s=s[:a]+''' const [editingField,setEditingField]=useState('')
 const dataRow=(group:'profile'|'org',key:string,label:string,type='text')=>{const id=group+'-'+key,editing=editingField===id,value=group==='profile'?profileDraft[key as keyof Profile]||'':orgDraft[key as keyof Organization];return <div className="account-detail-row" key={id}><label htmlFor={id}>{label}</label><div className="account-detail-value">{editing?<Input id={id} autoFocus type={type} required={key==='name'} value={value} onChange={e=>group==='profile'?setProfileDraft({...profileDraft,[key]:e.target.value}):setOrgDraft({...orgDraft,[key]:e.target.value})}/>:<span className={value?'':'account-detail-empty'}>{value||'Не указано'}</span>}</div><Button type="button" variant="ghost" onClick={()=>setEditingField(editing?'':id)}>{editing?'Готово':'Изменить'}</Button></div>}
'''+s[b:]
a=s.index(" {section==='profile'&&");b=s.index(" {section==='warehouses'&&",a)
s=s[:a]+''' {(section==='profile'||section==='organization')&&<div className="account-details"><form onSubmit={e=>{e.preventDefault();if(orgDraft.inn.trim()&&!/^(\\d{10}|\\d{12})$/.test(orgDraft.inn.trim())){setOrgError('ИНН должен содержать 10 или 12 цифр');return}saveProfile(e);saveOrg(e);setEditingField('')}}><section className="account-detail-section"><h2>Личные данные</h2>{dataRow('profile','name','Имя')}{dataRow('profile','email','Электронная почта','email')}{dataRow('profile','phone','Телефон','tel')}{dataRow('profile','telegram','Telegram')}</section><section className="account-detail-section"><h2>Организация</h2>{dataRow('org','name','Название фулфилмента')}{dataRow('org','inn','ИНН')}{dataRow('org','phone','Телефон','tel')}{dataRow('org','email','Электронная почта','email')}</section>{orgError&&<p role="alert" className="account-error">{orgError}</p>}{(profileChanged||orgChanged)&&<div className="account-detail-actions"><Button type="button" variant="outline" onClick={()=>{setProfileDraft(profile);setOrgDraft(organization);setEditingField('');setOrgError('')}}>Отменить</Button><Button type="submit" disabled={!profileDraft.name.trim()||!orgDraft.name.trim()}>Сохранить изменения</Button></div>}</form><section className="account-detail-section"><h2>Безопасность</h2><div className="account-detail-row"><span>Пароль</span><div className="account-detail-value"><span>••••••••</span><small>Смена пароля станет доступна после подключения сервера авторизации.</small></div><Button variant="ghost" disabled>Изменить</Button></div></section></div>}
'''+s[b:]
# Organization name is only required if changed, so saving a personal profile does not require creating organization.
s=s.replace("saveProfile(e);saveOrg(e);setEditingField('')","if(profileChanged)saveProfile(e);if(orgChanged)saveOrg(e);setEditingField('')")
s=s.replace("disabled={!profileDraft.name.trim()||!orgDraft.name.trim()}","disabled={!profileDraft.name.trim()||(orgChanged&&!orgDraft.name.trim())}")
p.write_text(s,encoding='utf-8')
